import{_ as a,o as p,c as o,a5 as n}from"./chunks/framework.Cooo9kuv.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"121-批量为音频插入广告片段","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["音频视频批处理"],"标签":["批量插入音频广告","音频广告插入"]},"headers":[],"relativePath":"md/音频视频批处理/121-批量为音频插入广告片段.md","filePath":"md/音频视频批处理/121-批量为音频插入广告片段.md"}'),r={name:"md/音频视频批处理/121-批量为音频插入广告片段.md"};function e(s,t,l,g,c,i){return p(),o("div",null,[...t[0]||(t[0]=[n('<p>批量为指定文件夹下所有音频插入指定片段的广告，插入的广告位置可以是在音频前面、音频后边、音频中间、随机前面、后边、中间位置。</p><p><strong>支持的音频格式：</strong>.mp3&#39;, &#39;.wav&#39;, &#39;.ogg&#39;, &#39;.flac&#39;, &#39;.aac&#39;, &#39;.m4a&#39;</p><p>支持子文件夹穿透，支持对子文件夹下音频文件进行相关操作。</p><h3 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h3><p>比如A文件夹下有很多音频文件，同时有B、C、D....等文件夹，打开程序后将A文件夹路径复制到程序中，指定一个添加广告后的文件夹路径，然后指定需要添加的广告音频片段，选择插入位置，选择是对所有音频进行操作还是随机对指定数量的音频进行操作，运行程序即可。</p><p>在添加完广告音频后输出后的文件夹内会保持与原A文件夹下文件结构保持一样。</p><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p>1、1 2 3选项就是字面意思</p><p>2、4随机插入就是随机对音频文件前面、中间、后边随机位置插入指定的音频片段</p><p>3、5 6 7 8 就是组合插入指定的一个片段</p><p>4、是否复制剩余文件：</p><p>已经添加广告音频的文件输出到了目标文件夹下，剩下的未添加的是不是也要复制呢，所以就有了一个选项，是不是复制剩余文件到目标文件夹下，如果复制则保持了与原文件夹结构完全一致。</p><p>不复制则只将处理过的音频放到目标文件夹下，与原文件夹结构也是一样的。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250228101821174070910195734.png" alt=""></p><p>5、对指定文件夹下音频的处理方式：</p><p>1、是对所有文件进行同一操作</p><p>2、随机选择指定数量文件进行统一操作</p><p>3、对所有文件排序后对奇数序列的文件进行统一操作</p><p>4、对所有文件排序后对偶数序列的文件进行统一操作</p><p>5、自定义对排序后的哪些文件进行操作，比如对A文件夹下 1 3 5 8 这几个文件进行统一操作，<strong>每个数字间使用空格隔开</strong>，不管你的文件名是什么，按照自然序列重新排序后，只需要输入第几个文件即可，如前面的 1 3 5 8 代表第一个文件，第3个文件，第五个文件，第8个文件....</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250228101913174070915351137.png" alt=""></p><h3 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h3><p>将apitool文件夹复制放到C盘根目录下，双击程序运行即可。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250226152344174055462453369.png" alt=""></p><h3 id="效果图" tabindex="-1">效果图 <a class="header-anchor" href="#效果图" aria-label="Permalink to &quot;效果图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250226152500174055470030937.png" alt=""></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250226152550174055475092526.png" alt=""></p><hr><p><strong>2.0版本更新：</strong></p><p>新增格式支持：.mp3&#39;, &#39;.wav&#39;, &#39;.ogg&#39;, &#39;.flac&#39;, &#39;.aac&#39;, &#39;.m4a&#39;</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统<br> 注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1535.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1535.html</a></p>',34)])])}const _=a(r,[["render",e]]);export{m as __pageData,_ as default};
